import { describe, expect, it } from "vitest";
import { formatSignedPercent, percentChange } from "./index";

describe("percentChange", () => {
  it("computes a gain and a loss", () => {
    expect(percentChange(100, 110)).toBeCloseTo(10);
    expect(percentChange(200, 150)).toBeCloseTo(-25);
  });

  it("returns null when the starting value is zero", () => {
    expect(percentChange(0, 5)).toBeNull();
  });
});

describe("formatSignedPercent", () => {
  it("adds a plus sign to gains and a minus sign to losses", () => {
    expect(formatSignedPercent(1.2636)).toBe("+1.26%");
    expect(formatSignedPercent(-5)).toBe("-5.00%");
  });

  it("shows no sign for a change that rounds to zero", () => {
    expect(formatSignedPercent(0)).toBe("0.00%");
    expect(formatSignedPercent(-0.001)).toBe("0.00%");
  });
});
// Pure financial calculations. No React, no network, no database.
// Only a generic helper lives here for now; real analysis comes in later exercises.

/** Percentage change from `from` to `to`. Returns null when `from` is 0. */
export function percentChange(from: number, to: number): number | null {
  if (from === 0) return null;
  return ((to - from) / Math.abs(from)) * 100;
}

/** Formats a percentage with an explicit sign and two decimals, e.g. "+1.26%" or "-5.00%". */
export function formatSignedPercent(value: number): string {
  const rounded = value.toFixed(2);
  // A change that rounds to zero carries no sign (avoids "-0.00%").
  if (Number(rounded) === 0) return "0.00%";
  return `${value > 0 ? "+" : ""}${rounded}%`;
}
import { formatSignedPercent, percentChange } from "@nasdaq-swipe/finance-core";

export interface StockCardProps {
  name: string;
  symbol: string;
  previousClose: number;
  lastPrice: number;
}

const usd = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });

export function StockCard({ name, symbol, previousClose, lastPrice }: StockCardProps) {
  const change = percentChange(previousClose, lastPrice);

  return (
    <article className="stock-card">
      <h2>
        {name} ({symbol})
      </h2>
      <p>{usd.format(lastPrice)}</p>
      <p>{change === null ? "Change unavailable" : `${formatSignedPercent(change)} today`}</p>
    </article>
  );
}
import type { StockCardProps } from "./StockCard";

export const sampleStocks: StockCardProps[] = [
  { name: "Apple Inc.", symbol: "AAPL", previousClose: 228.52, lastPrice: 231.4 },
  { name: "Microsoft Corp.", symbol: "MSFT", previousClose: 415.1, lastPrice: 409.85 },
  { name: "NVIDIA Corp.", symbol: "NVDA", previousClose: 120, lastPrice: 126 },
];

