import { describePe, formatSignedPercent, MARKET_PE, percentChange } from "@nasdaq-swipe/finance-core";

export interface StockCardProps {
  name: string;
  symbol: string;
  previousClose: number;
  lastPrice: number;
  pe: number;
}

