      <p>{usd.format(lastPrice)}</p>
      <p>{change === null ? "Change unavailable" : `${formatSignedPercent(change)} today`}</p>
      <p>P/E {pe.toFixed(1)}</p>
      <p>{describePe(pe, MARKET_PE)}</p>
    </article>
  );
}

